            "correctAnswer": 2,
            "explanation": "& (d)\n\n‘शून्यकाल’ (Zero Hour) िविशष्ट भारतीय संसदीय व्यवहार है। लोक सभा\nमें प्रश्नकाल के बाद का समय ‘शून्यकाल’ कहा जाता है, िजसकी अविध सा-\nमान्यत: अिधकतम 1 घंटा हो सकती है, िजसे ‘जीरो ऑवर’ (Zero Hour)\nभी कहा जाता है। यह सामान्यत: दोपहर 12 से 1 बजे तक का समय होता\nहै। पहले राज्य सभा में भी यही िस्थित थी‚ परंतु राज्य सभा में प्रश्नकाल\nकी अविध को वषर् 2014 में पिरवितर्त कर दोपहर 12 बजे से 1 बजे तक कर\nिदया गया और तदनुसार अब राज्य सभा में सवर्प्रथम 11 बजे से दस्तावेज\nसदन के पटल पर रखे जाते हैं‚ िजसके बाद सभापित की अनुमित के साथ\nतत्काल आवश्यक जनिहत के मुद्दे (शून्यकाल के तहत) उठाए जाते हैं और\nिफर िवशेष उल्लेख (Special Mentions) 12 बजे तक िलए जाते हैं। इस\nप्रकार अब राज्य सभा में शून्यकाल का समय प्रश्नकाल से पूवर् (सुबह 11\nबजे से दोपहर 12 बजे के बीच) हो गया है‚ जबिक लोक सभा में यह पूवर्वत\nप्रश्नकाल के बाद (दोपहर 12 बजे से अपराह्न 1 बजे के मध्य) है। संसदीय\nप्रिक्रया में शून्यकाल शब्द को औपचािरक मान्यता प्राप्त नहीं है। शून्यकाल में\nिकसी तत्काल आवश्यक जनिहत के मामले को उठाने के िलए सदस्य प्रितिदन\nअध्यक्ष/सभापित को पूवर् सूचना देते हैं। िकसी मामले को उठाने या न उठाने\nकी अनुमित या मामलों के क्रम का िनणर्य अध्यक्ष/सभापित पर िनभर्र करता\nहै। इस दौरान सदन का कोई सदस्य अत्यंत महत्वपूणर् िवषयों से संबंिधत प्रश्न\nमंित्रयों से पूछ सकता है और उत्तर देने को कह सकता है।\n\n*\n‘शून्यकाल’ संसदीय व्यवस्था को िकस देश की देन है? – भारत की\n*\nलोक सभा में ‘शून्यकाल’ की अविध सामान्यत: अिधक से अिधक\nिकतनी हो सकती है?\n– एक घंटा"
