            "explanation": "भारतीय संिवधान के प्रथम संशोधन‚ 1951 द्वारा संिवधान में अन्य पिरवतर्नों\nके साथ दो नए अनुच्छेदों 31-क एवं 31-ख तथा नौवीं अनुसूची (कुछ अिध-\nिनयमों और िविनयमों का िविधमान्यकरण) को शािमल िकया गया‚ िजसका\nउद्देश्य मूलत: कुछ राज्यों में कृिष एवं कृिष-भूिम संबंधी सुधारों के संरक्षण\nहेतु बनाए गए भूिम सुधार कानूनों को न्याियक चुनौती से संरिक्षत करना था।\nवतर्मान में नौवीं अनुसूची में अब केवल भूिम सुधार संबंधी ही नहीं, बिल्क\nअन्य िवषयों से संबंिधत कई िविशष्ट अिधिनयम भी शािमल हैं, तथा साथ\nही आई.आर. कोएल्हो वाद (2007) के सवĝच्च न्यायालय के िनणर्य के तहत\n24 अप्रैल, 1973 के बाद नौवीं अनुसूची में डाले गए कानून ‘मूल संरचना’\nके उल्लंघन की िस्थित में न्याियक समीक्षा से पूरी तरह सुरिक्षत नहीं हैं।"
